    if (!match) return 0;
    const base = Number(match[1].replace(/,/g, ""));
    if (!Number.isFinite(base)) return 0;
    const multiplier = match[2] === "亿" ? 100000000 : match[2] === "万" ? 10000 : match[2] ? 1000 : 1;
